import{Functions,Locale}from"Beckhoff.TwinCAT.HMI.Framework/index.esm.js";export function GetLocalizedText(key){const control=/^Control:(?::(.+?)::|([^;]+);)(.+)$/.exec(key);if(control)return new Locale.ControlLocalization(control[1]??control[2]).getText(control[3]);const func=/^Function:(?::(.+?)::|([^;]+);)(.+)$/.exec(key);if(func)return new Locale.FunctionLocalization(func[1]??func[2]).getText(func[3]);const pkg=/^Package:(?::(.+?)::|([^;]+);)(.+)$/.exec(key);if(pkg)return new Locale.PackageLocalization(pkg[1]??pkg[2]).getText(pkg[3]);const framework=/^Framework;(.+)$/.exec(key)??/^Framework::(.+)$/.exec(key);if(framework)return(new Locale.FrameworkLocalization).getText(framework[1]);const application=/^Application;(.+)$/.exec(key)??/^Application::(.+)$/.exec(key);return application?(new Locale.ApplicationLocalization).getText(application[1]):(new Locale.ApplicationLocalization).getText(key)}Functions.registerFunctionEx("GetLocalizedText","TcHmi.Functions.Beckhoff",GetLocalizedText,{injectInGlobalObject:!0});